from dsl import *
rnd("변경_요동",[1,2],"요동의 삼밭",
 "요동의 눈 덮인 골짜기. 삼꾼들이 움막 앞에 모여 있다. 올해 캔 산삼을 조정의 채삼관이 반값에 거두어 가겠다고 한다. 싫으면 밀수꾼으로 몰겠다고. 삼꾼 우두머리가 낯선 무인인 나를 보고 눈을 빛낸다. \"길손, 중원 사람이오? 중원에서는 이런 삼 한 뿌리가 얼마요?\"",
 [C("제값을 일러 주고 채삼관 앞에서 그 값을 다시 말한다",O("채삼관은 나를 한참 보다가 값을 반의 반쯤 올렸다. 관의 값은 그렇게 조금씩만 움직인다. 삼꾼들이 잔뿌리 한 줌을 싸 주었다.",alignment=AL(j=40),stats={"internal":4},fame=10)),
  C("삼을 사서 중원에 내다 팔 셈을 한다",O("관의 값보다 조금 더 쳐 주고 스무 뿌리를 샀다. 중원에 닿았을 때 값은 다섯 곱이 되어 있었다.",alignment=AL(s=40),silver=120),req={"min_silver":40}),
  C("눈밭에서 삼꾼들의 호흡을 배운다",O("삼꾼은 삼을 보면 숨부터 죽인다. 삼이 달아난다는 것이다. 사흘을 따라다니니 내 숨도 눈 위에 김을 남기지 않게 되었다.",stats={"internal":5,"mind":2})),
  C("채삼관의 수레를 밤에 턴다",O("관의 수레에는 삼꾼들에게서 반값에 거둔 삼이 그득했다. 삼꾼들은 이튿날 밀수꾼으로 몰려 문초를 받았다. 삼은 중원에서 좋은 값을 받았다.",alignment=AL(m=50),silver=180,stats={"external":2}))])
rnd("변경_차마고도",[1,2,3],"차마고도의 마방",
 "운남에서 설산으로 넘어가는 벼랑길. 차를 실은 말 서른 필의 마방이 길을 막고 섰다. 앞쪽 벼랑이 무너져 말 한 필이 겨우 지나갈 틈만 남았다. 마방의 우두머리가 담뱃대를 물고 말한다. \"돌아가면 한 달, 건너면 반나절이오. 말이 한 필 떨어질 때마다 차 여섯 덩이가 같이 떨어지지.\"",
 [C("벼랑 쪽에 서서 말을 한 필씩 건넨다",O("서른 필이 다 건넜다. 마지막 말이 미끄러질 때 고삐를 잡은 손바닥이 벗겨졌다. 우두머리가 가장 오래 묵힌 차 한 덩이를 내주었다. 마시니 단전이 더워진다.",alignment=AL(j=40),stats={"external":4,"internal":3},hp_pct=-10)),
  C("길잡이 삯을 받고 건넨다",O("삯은 차 석 덩이였다. 설산 너머 장터에서 은자로 바꿨다.",alignment=AL(s=30),silver=90,stats={"external":3})),
  C("무너진 벼랑을 내력으로 깎아 길을 넓힌다",O("반나절을 쳤다. 길이 한 뼘 넓어졌고 팔이 사흘 동안 올라가지 않았다. 마방 사람들은 그 자리에 내 이름을 새기겠다고 했다. 이름은 일러 주지 않았다.",stats={"external":6},mastery=8,fame=10)),
  C("앞선 말 두 필을 짐째 벼랑으로 밀어 틈을 넓힌다",O("차 열두 덩이가 골짜기로 떨어졌다. 나머지 스물여덟 필은 쉽게 건넜다. 우두머리는 셈이 맞는다는 얼굴과 사람이 아니라는 얼굴을 번갈아 했다.",alignment=AL(m=40),stats={"external":4,"mind":2}))])
rnd("변경_동해",[2,3],"동해의 소금 포구",
 "동해의 포구. 염전 일꾼들이 소금 가마니를 지고 줄을 섰고, 바다 쪽에서는 검은 돛의 배 두 척이 물때를 기다린다. 해적이다. 포구의 늙은 염상이 말한다. \"해마다 이맘때 오지. 소금 삼백 가마를 내주면 불은 안 지르고 간다오. 관군은 사흘 거리에 있고.\"",
 [C("포구 사람들과 방파제에 선다",O("배 한 척이 닻을 올리고 돌아갔고, 한 척은 뭍에 닿았다가 쫓겨 갔다. 염상이 소금 대신 말린 전복을 한 꾸러미 싸 주었다.",battle="떠돌이패",foe="검은 돛의 해적 패",foe_line="\"소금 삼백 가마에 목숨을 거는 놈은 처음 본다.\"",alignment=AL(j=60),stats={"external":5,"martial":4},fame=20)),
  C("해적 두목과 소금 값을 흥정해 준다",O("삼백 가마는 이백 가마가 되었다. 염상은 고맙다 했고 해적 두목은 다음에도 불러 달라 했다. 양쪽에서 삯을 받았다.",alignment=AL(s=50),silver=150,stats={"mind":4})),
  C("밤에 해적선에 올라 두목의 목을 걸어 둔다",O("아침에 검은 돛 두 척은 주인 없이 떠 있었다. 포구 사람들은 고맙다는 말을 하면서도 한 걸음씩 물러섰다.",alignment=AL(m=60),stats={"external":5,"martial":5},fame=10))])
rnd("변경_서역",[2,3,4],"옥문관 밖의 객잔",
 "옥문관을 나서면 모래뿐이다. 모래바람 속 객잔에 서역의 대상들이 낙타를 묶었다. 푸른 눈의 상인이 유리병과 향료를 펼쳐 놓고 서툰 말로 묻는다. \"동쪽은 전쟁이오? 비단 값이 오르오, 내리오?\" 옆 탁자에서는 곤륜의 젊은 도사 둘이 그 말을 받아 적는다.",
 [C("아는 대로 일러 준다",O("전란에는 비단보다 약재와 쇠가 오른다고 했다. 상인은 낙타 열 필의 짐을 그 자리에서 바꿔 실었다. 고맙다며 서역의 붉은 약초 한 줌을 주었다.",stats={"mind":4,"internal":3},fame=5)),
  C("서역의 병기를 구경하고 겨뤄 본다",O("휘어진 칼과 쇠사슬 달린 추. 대상의 호위가 웃으며 받아 주었다. 중원의 초식과는 숨 쉬는 자리가 다르다.",battle="떠돌이패",spar=True,foe="대상의 호위 사마르",foe_line="\"동쪽의 무인. 모래 위에서는 발이 다르다.\"",stats={"martial":5,"external":3},mastery=8)),
  C("비단 값을 거꾸로 일러 주고 싸게 산다",O("상인은 유리병을 헐값에 넘겼다. 관 안쪽에서 다섯 곱에 팔았다. 다음에 옥문관을 지날 때는 얼굴을 가려야 할 것이다.",alignment=AL(s=50),silver=140)),
  C("모래바람이 부는 밤에 대상의 짐을 턴다",O("모래가 발자국을 지웠다. 향료 두 자루와 유리병 한 궤. 푸른 눈의 상인은 아침에 한참 동쪽 말로 욕을 했다. 반은 알아듣지 못했다.",alignment=AL(m=50),silver=170,stats={"external":3}))])
